int main(){int n,m;cin>>n>>m;vector<pair<int,int>>edges(m);for(auto&e:edges)cin>>e.first>>e.second;vector<vector<int>>adj(n+1);for(auto&e:edges){adj[e.first].push_back(e.second);adj[e.second].push_back(e.first);}vector<int>color(n+1,-1);bool ok=true;for(int s=1;s<=n&&ok;s++){if(color[s]!=-1)continue;color[s]=0;queue<int>q;q.push(s);while(!q.empty()&&ok){int u=q.front();q.pop();for(int v:adj[u]){if(color[v]==-1){color[v]=color[u]^1;q.push(v);}else if(color[v]==color[u]){ok=false;break;}}}}cout<<(ok?"YES":"NO")<<"\n";return 0;}

